import{N as e,d as t,m as n}from"./etRUTm8X.js";import{n as r}from"#entry";var i={};function a(r,i){return e(),t(`div`,null,[...i[0]||=[n(`<div class="page-h" data-v-ed872da5><div data-v-ed872da5><h1 data-v-ed872da5>Help</h1><p data-v-ed872da5>Where things are, and every command you can use in game or in the console</p></div></div><div class="grid g2" style="margin-bottom:16px;" data-v-ed872da5><div class="card" data-v-ed872da5><div class="card-h" data-v-ed872da5><h3 data-v-ed872da5>Quick start</h3></div><ol class="hl" data-v-ed872da5><li data-v-ed872da5><b data-v-ed872da5>Games</b> → <i data-v-ed872da5>Set up game hub</i> creates the lobby and one world per mode. <i data-v-ed872da5>New room</i> pins a room with its own player cap and bots; <i data-v-ed872da5>New world</i> makes a regular world.</li><li data-v-ed872da5><b data-v-ed872da5>Settings</b> sets the server name, message of the day and an optional join password. The admin password lives in the server&#39;s <code data-v-ed872da5>ADMIN_PASSWORD</code> environment variable.</li><li data-v-ed872da5>Rooms open and close by themselves as games fill up. The <b data-v-ed872da5>capacity</b> meter shows how many player slots the server can still carry and why it is limited.</li><li data-v-ed872da5>Make a <b data-v-ed872da5>Backup</b> before risky changes. Worlds autosave every 30 s.</li></ol></div><div class="card" data-v-ed872da5><div class="card-h" data-v-ed872da5><h3 data-v-ed872da5>What each page does</h3></div><ul class="hl" data-v-ed872da5><li data-v-ed872da5><b data-v-ed872da5>Overview</b> live health, live games, capacity, charts, Save all / Backup / Announce / Maintenance.</li><li data-v-ed872da5><b data-v-ed872da5>Games</b> every world and room, live state, lobby portal switch, backups. <b data-v-ed872da5>Bots</b> global and per-game bot controls, summon and clear.</li><li data-v-ed872da5><b data-v-ed872da5>Players</b> click a name for details; kick, ban, mute, op, coins, teleport. <b data-v-ed872da5>Live map</b> block-accurate map with players and creatures.</li><li data-v-ed872da5><b data-v-ed872da5>Economy</b> leaderboard, bounties, market prices and wallets. <b data-v-ed872da5>Security</b> maintenance, allowlist, bans, audit log.</li></ul></div></div><div class="grid g3" data-v-ed872da5><div class="card" data-v-ed872da5><div class="card-h" data-v-ed872da5><h3 data-v-ed872da5>Players</h3></div><ul class="cm" data-v-ed872da5><li data-v-ed872da5><code data-v-ed872da5>/rooms [mode]</code> open games</li><li data-v-ed872da5><code data-v-ed872da5>/quick [mode]</code> jump into the best room</li><li data-v-ed872da5><code data-v-ed872da5>/join &lt;code|mode&gt;</code></li><li data-v-ed872da5><code data-v-ed872da5>/create &lt;mode&gt; [players] [bots] [skill] [public]</code></li><li data-v-ed872da5><code data-v-ed872da5>/lobby</code> · <code data-v-ed872da5>/party</code> · <code data-v-ed872da5>/msg &lt;p&gt; text</code></li><li data-v-ed872da5><code data-v-ed872da5>/ping</code> · <code data-v-ed872da5>/stats</code> · <code data-v-ed872da5>/list</code> · <code data-v-ed872da5>/help</code></li></ul></div><div class="card" data-v-ed872da5><div class="card-h" data-v-ed872da5><h3 data-v-ed872da5>Operators</h3></div><ul class="cm" data-v-ed872da5><li data-v-ed872da5><code data-v-ed872da5>/kick /ban /unban /op /deop /mute /unmute</code></li><li data-v-ed872da5><code data-v-ed872da5>/heal [p]</code> · <code data-v-ed872da5>/bring &lt;p&gt;</code> · <code data-v-ed872da5>/tp x y z|p</code></li><li data-v-ed872da5><code data-v-ed872da5>/round start|end|restart</code></li><li data-v-ed872da5><code data-v-ed872da5>/room create|close|list</code></li><li data-v-ed872da5><code data-v-ed872da5>/announce text</code> · <code data-v-ed872da5>/say text</code></li><li data-v-ed872da5><code data-v-ed872da5>/capacity</code> · <code data-v-ed872da5>/status</code> · <code data-v-ed872da5>/save</code></li></ul></div><div class="card" data-v-ed872da5><div class="card-h" data-v-ed872da5><h3 data-v-ed872da5>Bots &amp; world</h3></div><ul class="cm" data-v-ed872da5><li data-v-ed872da5><code data-v-ed872da5>/bot add [n] [skill] [name]</code> summon</li><li data-v-ed872da5><code data-v-ed872da5>/bot count n</code> · <code data-v-ed872da5>/bot auto</code> · <code data-v-ed872da5>/bot skill lvl</code></li><li data-v-ed872da5><code data-v-ed872da5>/bot pause|resume|clear|remove [n]|list</code></li><li data-v-ed872da5><code data-v-ed872da5>/time day|night</code> · <code data-v-ed872da5>/weather clear|rain|storm</code></li><li data-v-ed872da5><code data-v-ed872da5>/spawn pig|zombie|villager|boss [n]</code> · <code data-v-ed872da5>/kill mobs</code></li><li data-v-ed872da5><code data-v-ed872da5>/give &lt;p&gt; coins</code> · <code data-v-ed872da5>/seed</code></li></ul></div></div>`,3)]])}var o=r(i,[[`render`,a],[`__scopeId`,`data-v-ed872da5`]]);export{o as default};